(() => {
  if(document.body.dataset.page!=='visits')return;
  const d=window.SCHOOL_DATA,v=d.visit115,main=document.getElementById('main');
  const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>Number(n).toLocaleString('zh-TW');
  const resource=id=>d.resources.find(r=>r.id===id);
  const link=id=>{const r=resource(id);return r?`<a href="resource.html?id=${id}">${e(r.title)} →</a>`:'';};
  const read=(book,label,chapter,page)=>`<a class="text-link" href="reader.html?book=${book}${chapter?'&chapter='+chapter:''}${page?'&page='+page:''}">${e(label)} ↗</a>`;
  const picture=id=>{const r=resource(id);return r?.cover&&d.assets[r.cover]?d.assets[r.cover].src:r?.coverPage;};
  const table=(heads,rows)=>`<div class="visit-table" tabindex="0" role="region" aria-label="${e(heads.join('、'))}"><table><thead><tr>${heads.map(x=>`<th scope="col">${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const downloads=[['115-visit-plan-and-forms.odt','訪視計畫與三份表件 ODT'],['115-visit-notice.pdf','115年訪視通知 PDF'],['114-approved-plan.pdf','114修正核定計畫 PDF'],['114-cip-grant-letter.pdf','114原民會核定函 PDF'],['114-county-grant-letter.pdf','114縣府核定函 PDF'],['114-grant-allocation.pdf','114核定經費表 PDF'],['114-second-grant-allocation.pdf','114第二期款核定表 PDF']];
  // 學校簡報：一次看一張，可以左右切換、滑動、點縮圖跳頁，按「放大看」用網站原本的照片檢視
  const b=v.briefing,slides=(b?.slides||[]).filter(x=>d.assets[x.photo]);
  const deck=slides.length?`<div id="briefing" class="visit-briefing"><div class="briefing-head"><div><p class="eyebrow">${b.minutes}分鐘學校簡報</p><h3>${e(b.title)}</h3></div><span>${slides.length} 張 · ${e(b.version)}</span></div><div class="briefing-stage"><button type="button" class="briefing-nav" data-step="-1" aria-label="上一張">←</button><img src="${e(d.assets[slides[0].photo].src)}" width="${d.assets[slides[0].photo].width}" height="${d.assets[slides[0].photo].height}" alt="${e(slides[0].title)}"><button type="button" class="briefing-nav" data-step="1" aria-label="下一張">→</button></div><div class="briefing-bar"><button type="button" class="briefing-step" data-step="-1" aria-label="上一張">←</button><b aria-live="polite">1 / ${slides.length}</b><button type="button" class="briefing-step" data-step="1" aria-label="下一張">→</button><p>${e(slides[0].title)}</p><button type="button" class="pill" data-zoom>放大看 ↗</button></div><div class="briefing-thumbs" role="list">${slides.map((x,i)=>`<button type="button" role="listitem" data-go="${i}" aria-label="第${i+1}張：${e(x.title)}"${i?'':' aria-current="true"'}><img src="${e(d.assets[x.photo].thumb)}" width="480" height="270" alt="" loading="lazy" decoding="async"><span>${i+1}</span></button>`).join('')}</div><div class="slide-deck" hidden>${slides.map((x,i)=>`<button type="button" class="photo-open" data-photo="${e(x.photo)}" data-caption="${e(b.title)}｜第${i+1}張：${e(x.title)}"></button>`).join('')}</div></div>`:'';
  const room=window.SalimpoRoom;
  main.innerHTML=`<header class="page-heading visit-heading"><div class="breadcrumb"><a href="index.html">首頁</a><span>/</span><a href="reception.html">會客室</a><span>/</span><span>原民會訪視</span></div><p class="eyebrow">會客室 · 山海教育，一起看見</p><h1>原民會訪視</h1><p>從一張課程地圖，到孩子的作品與部落的陪伴。沿著四大面向，走進寧埔的實驗教育。</p><div class="visit-date"><strong>${e(v.dateLabel)} ${e(v.time)}</strong><span>寧埔國小 · 120分鐘</span>${read(v.officialBook,'訪視計畫全文')}</div>${room?room.tabs('visits'):''}</header>
  <div class="page-body visit-page"><nav class="visit-domains" aria-label="四大訪視面向">${v.groups.map((g,i)=>`<a href="#${g.id}" class="visit-domain"><span>0${i+1}</span><b>${g.weight}<small>%</small></b><strong>${e(g.title)}</strong><small>${g.items.length}項檢視重點</small></a>`).join('')}</nav>
  <nav class="visit-jumps" aria-label="專區內容"><a href="#flow">訪視流程</a>${v.briefing?'<a href="#briefing">學校簡報</a>':''}<a href="#lessons">教案教材</a><a href="#training">教師增能</a><a href="#student">學生學習</a><a href="#accounts">經費資料</a><a href="#forms">官方表件</a><a href="#library">完整資料</a></nav>
  <section id="flow" class="visit-section"><div class="visit-section-title"><p class="eyebrow">一起展開這場對話</p><h2>120分鐘，從課堂走進山海</h2></div><ol class="visit-flow">${[['5','主持人開場'],['20','學校簡報'],['80','書面資料審查'],['15','綜合座談']].map(([n,t])=>`<li><b>${n}<small>分鐘</small></b><strong>${t}</strong></li>`).join('')}</ol><p>書面資料備妥計畫、課程內容、學生學習成果與經費紀錄；教案以紙本詳案呈現，並列出各年級實際授課總節數及教案量。教師增能紀錄包含主題、日期、時長與內容。</p>${deck}<details><summary>20分鐘學校簡報｜建議閱讀順序</summary><ol><li>3分鐘：核定目標、114基礎與115・116螺旋課程。${link('VISIT-002')}${link('PLAN-002')}</li><li>8分鐘：文化領域、課程設計、詳案、教材及評量。${link('VISIT-005')}</li><li>4分鐘：學生作品、族語與展演比賽。${link('VISIT-007')}<a href="stories.html">展演與比賽成果 →</a></li><li>5分鐘：教師增能、部落合作、經費執行與精進。${link('VISIT-004')}${link('VISIT-003')}<a href="partnerships.html">合作計畫 →</a></li></ol></details></section>
  ${v.groups.map((g,i)=>`<section id="${g.id}" class="visit-section visit-evidence"><div class="visit-section-title"><p class="eyebrow">0${i+1} / 訪視面向 · ${g.weight}%</p><h2>${e(g.title)}</h2><p>${e(g.intro)}</p></div>${picture(g.cover)?`<img class="visit-banner" src="${e(picture(g.cover))}" alt="${e(g.title)}的學習紀錄" loading="lazy">`:''}<div class="visit-items">${g.items.map(x=>`<article class="visit-item"><div class="visit-item-title"><span>${x.code}</span><h3>${e(x.title)}</h3><b>${x.weight}%</b></div>${room?room.evidence(x):`<div class="visit-links">${x.resources.map(link).join('')}${x.read?read(x.read.book,x.read.label,x.read.chapter):''}</div>`}</article>`).join('')}</div></section>`).join('')}
  <section id="lessons" class="visit-section"><p class="eyebrow">打開一堂課的設計</p><h2>教案詳案・教材・學習資源</h2><p>31個閱讀主題依學期、年段與內容整理，包含教學目標、族語詞彙及教學紀錄。閱讀主題數與完成詳案套數、各年級授課節數分別計算。</p><div class="visit-actions"><a class="button primary" href="lessons.html">依主題走進山海探索站 →</a>${read('visit115Evidence','教案與教材完整資料',2)}${read('report114b','教材、出版與數位資源',23)}</div><details><summary>展開31個教案閱讀主題</summary>${table(['學期','年段','主題','教案單元','閱讀'],d.lessons.map(l=>[`${l.year}・${l.semester===1?'上':'下'}`,e(l.band),e(l.topic),e(l.title),read(l.book,`${l.start}–${l.end}頁`,null,l.start)]))}</details><div class="visit-digital"><h3>從課堂走進互動教材</h3><div class="visit-links"><a href="https://laierin615.github.io/yuan-ke-jie-mi/" target="_blank" rel="noopener noreferrer">原科解密 ↗</a><a href="https://laierin615.github.io/laierindateng/" target="_blank" rel="noopener noreferrer">Dateng野菜教材 ↗</a><a href="https://mipacing-pov-game.nbps14467101.chatgpt.site/game" target="_blank" rel="noopener noreferrer">Mipacing情境遊戲 ↗</a><a href="https://salimpo-curriculum.nbps14467101.chatgpt.site/#/mitesel" target="_blank" rel="noopener noreferrer">Mitesel十字繡 ↗</a></div></div></section>
  <section id="training" class="visit-section"><p class="eyebrow">老師也一起學習</p><h2>八場研習，文化走進教學</h2><p>114學年度上學期5場、下學期3場。下學期三場已載起訖時間，合計7小時；「—」表示報告未載時長，個別教師時數依簽到與研習證明核計。</p>${table(['日期','研習主題與內容','講師／單位','時間／時長','閱讀'],v.training.map(t=>[e(t.date),`<strong>${e(t.title)}</strong><p>${e(t.content)}</p>`,e(t.lecturer),t.hours?`${e(t.time)}<br><b>${t.hours}小時</b>`:'—',read(t.book,'研習紀錄',t.chapter,t.page)]))}<div id="visit-training-photos" class="visit-photo-grid"></div>${read('visit115Evidence','教師增能完整圖文',1)}</section>
  <section id="student" class="visit-section"><p class="eyebrow">孩子的學習，留下足跡</p><h2>作品、評量與族語表達</h2><div class="visit-language"><div><b>10</b><span>初級認證累計人次</span></div><div><b>6</b><span>中級認證累計人次</span></div><div><b>2</b><span>中高級聽力與口說<br>單科通過人次</span></div><div><b>12</b><span>位孩子通過認證<br>（扣除跨梯次重複）</span></div></div><p>人次為歷年累計，與自評報告書一致；中高級單科通過與整級認證分別呈現。課程評量涵蓋文化知識、實作、口語表達與合作歷程，搭配各年段作品及教師紀錄，可依114下學期成果報告分項閱讀。</p><div class="visit-actions">${read('report114b','族語與認證紀錄',18)}${read('report114b','各年段學習成果',21)}${read('report114b','課程評量規準',14)}<a class="button" href="stories.html">所有展演與比賽成果 →</a></div></section>
  <section id="accounts" class="visit-section"><p class="eyebrow">支持課程的每一筆經費</p><h2>114結報與115修正版預算</h2><div class="visit-money"><div><span>114核定</span><b>${money(v.finance.approved)}<small>元</small></b></div><div><span>114累計結報</span><b>${money(v.finance.reported)}<small>元</small></b></div><div><span>核定減結報差額</span><b>${money(v.finance.difference)}<small>元</small></b></div></div><p>核定經常門126萬元、資本門4萬元。差額73,528元為核定減累計結報，繳回與結案狀態依主計紀錄核對。</p><details><summary>114核定與累計結報明細</summary>${table(['項目','核定（元）','累計結報（元）','差額（元）'],v.finance.items114.map(x=>[e(x.title),money(x.approved),money(x.reported),money(x.difference)]))}<a href="${d.assets[v.finance.image].src}" target="_blank" rel="noopener noreferrer"><img class="visit-finance-image" src="${d.assets[v.finance.image].src}" alt="114學年度經費分攤結報表" loading="lazy"></a></details><details><summary>115修正版預算｜${money(v.finance.budget115)}元</summary><p>115年8月1日至116年7月31日。經常門1,376,963元、資本門100,000元，呈現修正編列數，執行依正式核定函。</p>${table(['項目','單價（元）','數量','修正編列（元）'],v.finance.items115.map(x=>[e(x.title),money(x.unit),e(x.quantity),money(x.amount)]))}</details><details><summary>核銷原件目錄｜29份・990頁</summary><p>依學年度及檔名查找。逐筆支出、原始憑證及簽章於校內核銷原件查閱。</p>${table(['學年度','原件名稱','頁數'],v.finance.catalog.map(x=>[e(x.year),e(x.name),x.pages]))}</details><div class="visit-actions">${read('visit115Finance','經費彙整全文')}${read('visit115Approvals','核定函與經費表')}</div></section>
  <section id="forms" class="visit-section"><p class="eyebrow">把課程、證據與精進接起來</p><h2>官方訪視表件</h2><div class="visit-forms">${v.forms.map((f,i)=>`<article><span>0${i+1}</span><h3>${e(f.title)}</h3>${read(f.book,'翻閱完整表格',f.chapter)}</article>`).join('')}</div><p>表件保留官方空白欄位，供學校自我檢核、評析與委員評分使用。</p><div class="visit-actions"><a class="button primary" href="attachments/visit115/115-visit-plan-and-forms.odt" download>下載可編輯計畫與表件 ODT ↓</a>${read('report114b','教學自評與精進方向',28)}<a class="text-link" href="reviews.html">實驗教育評鑑・七大面向24項 →</a></div></section>
  <section id="library" class="visit-section"><p class="eyebrow">完整資料，一次找齊</p><h2>訪視資料架</h2><div class="visit-library">${v.resources.map(id=>{const r=resource(id),src=picture(id);return `<article>${src?`<img src="${e(src)}" alt="" loading="lazy">`:''}<div><span class="eyebrow">${e(r.type)}</span><h3>${link(id)}</h3><p>${e(r.summary)}</p>${read(r.reading[0].book,'閱讀完整資料',r.reading[0].chapter)}</div></article>`;}).join('')}</div><details><summary>原件下載｜7份</summary><div class="visit-links">${downloads.map(([f,l])=>`<a href="attachments/visit115/${f}" download>${l} ↓</a>`).join('')}</div></details></section></div>`;
  const box=main.querySelector('#briefing');
  if(box){let at=0;const img=box.querySelector('.briefing-stage img'),count=box.querySelector('.briefing-bar b'),caption=box.querySelector('.briefing-bar p'),thumbs=[...box.querySelectorAll('[data-go]')];
   const show=i=>{at=(i+slides.length)%slides.length;const a=d.assets[slides[at].photo];img.src=a.src;img.alt=slides[at].title;count.textContent=`${at+1} / ${slides.length}`;caption.textContent=slides[at].title;thumbs.forEach((t,j)=>t.toggleAttribute('aria-current',j===at));const t=thumbs[at],strip=t.parentNode;if(t.offsetLeft<strip.scrollLeft||t.offsetLeft+t.offsetWidth>strip.scrollLeft+strip.clientWidth)strip.scrollTo({left:t.offsetLeft-(strip.clientWidth-t.offsetWidth)/2,behavior:'smooth'});new Image().src=d.assets[slides[(at+1)%slides.length].photo].src;};
   box.querySelectorAll('[data-step]').forEach(x=>x.onclick=()=>show(at+Number(x.dataset.step)));
   thumbs.forEach(x=>x.onclick=()=>show(Number(x.dataset.go)));
   box.querySelector('[data-zoom]').onclick=()=>box.querySelectorAll('.slide-deck .photo-open')[at].click();
   img.onclick=()=>box.querySelector('[data-zoom]').click();
   box.querySelector('.briefing-stage').addEventListener('keydown',ev=>{if(ev.key==='ArrowLeft')show(at-1);if(ev.key==='ArrowRight')show(at+1);});
   let x0=null;img.addEventListener('touchstart',ev=>{x0=ev.touches[0].clientX;},{passive:true});img.addEventListener('touchend',ev=>{if(x0===null)return;const dx=ev.changedTouches[0].clientX-x0;x0=null;if(Math.abs(dx)>40)show(at+(dx<0?1:-1));});}
  fetch('books/report114b.json').then(r=>r.json()).then(b=>{const collect=bs=>bs.flatMap(x=>[...(x.images||[]),...(x.kind==='table'?x.rows.flatMap(row=>row.flatMap(collect)):[])]),ids=collect(b.chapters[14].blocks);main.querySelector('#visit-training-photos').innerHTML=ids.slice(0,6).map(id=>`<a href="reader.html?book=report114b&chapter=15"><img src="${e(d.assets[id].src)}" alt="教師文化共備與研習現場" loading="lazy"></a>`).join('');}).catch(()=>{});
})();
